// Real installed-plugin HTML, native export, then authored SEO metadata rebuild.
import assert from 'node:assert/strict';import {mkdtemp,readFile,writeFile,rm} from 'node:fs/promises';import {tmpdir} from 'node:os';import path from 'node:path';import {load} from 'cheerio';
import {extract} from '../../engine/extract.mjs';import {generate} from '../../engine/generate.mjs';import {run} from '../../engine/pipeline.mjs';import {parseContent,YAML} from '../../scripts/source-project.mjs';
const kind=process.argv[2]||'yoast',presets={aioseo:{port:9425,plugin:'all-in-one-seo-pack',version:'5.0.3',selector:'script.aioseo-schema'},yoast:{port:9423,plugin:'wordpress-seo',version:'28.7',selector:'script.yoast-schema-graph'},rankmath:{port:9424,plugin:'seo-by-rank-math',version:'1.0.280',selector:'script.rank-math-schema'}};
const preset=presets[kind];if(!preset)throw Error('Unknown installed SEO fixture: '+kind);
const origin=process.argv.find(arg=>arg.startsWith('--origin='))?.slice(9)||'http://127.0.0.1:'+preset.port;assert.equal(new URL(origin).hostname,'127.0.0.1','SEO checks require a loopback fixture');assert.equal(new URL(origin).origin,origin,'Pass an origin without a path');const dir=await mkdtemp(path.join(tmpdir(),'installed-seo-'));try{
 const pages=[];for(const route of ['/','/editorial-guide/','/unlisted-guide/','/field-note-02/']){const r=await fetch(origin+route);assert.equal(r.status,200);const html=await r.text(),p=extract(html,origin+route);p.styles=[];pages.push(p);if(route.includes('guide')){const $=load(html),prefix=route==='/editorial-guide/'?'Editorial':'Unlisted';assert.equal($('title').text(),prefix+' search title');assert.equal($('meta[property="og:title"]').attr('content'),prefix+' social title');assert.equal($('meta[name="twitter:title"],meta[property="twitter:title"]').attr('content'),prefix+' card title');assert.ok($(preset.selector).length);if(route==='/unlisted-guide/')assert.match(p.robots,/noindex/);}}
 await generate({source:origin+'/',identity:{title:'Community Journal'},design:{},navigation:[],metrics:{},pages,media:[]},dir);
 await run(process.execPath,['scripts/build.mjs','--site-url','https://export.example','--base-path','/preview'],{cwd:dir,timeout:120000});
 const output=route=>readFile(path.join(dir,'output',route,'index.html'),'utf8');let $=load(await output('editorial-guide'));assert.equal($('title').text(),'Editorial search title');assert.equal($('h1').text().trim(),'Editorial guide');assert.equal($('meta[property="og:title"]').attr('content'),'Editorial social title');assert.equal($('meta[name="twitter:title"]').attr('content'),'Editorial card title');assert.equal($('link[rel=canonical]').attr('href'),'https://export.example/preview/editorial-guide/');
 const graph=$('script[type="application/ld+json"]').text();assert.ok(graph.includes('https://export.example/preview/'));assert.ok(!graph.includes(origin));assert.match(load(await output('unlisted-guide'))('meta[name=robots]').attr('content'),/noindex/);const sitemap=await readFile(path.join(dir,'output/sitemap.xml'),'utf8');assert.ok(!sitemap.includes('/unlisted-guide/'));
 const routes=JSON.parse(await readFile(path.join(dir,'routes.json'),'utf8')),record=routes.find(r=>r.route==='/editorial-guide/'),file=path.join(dir,'content',record.collection,record.slug+'.md'),parsed=parseContent(await readFile(file,'utf8'),file);parsed.meta.seo_title='Authored search title';parsed.meta.description='Authored search description.';parsed.meta.social['og:title']=['Authored social title'];await writeFile(file,'---\n'+YAML.stringify(parsed.meta)+'---\n'+parsed.body);
 await run(process.execPath,['scripts/build.mjs','--site-url','https://export.example','--base-path','/preview'],{cwd:dir,timeout:120000});$=load(await output('editorial-guide'));assert.equal($('title').text(),'Authored search title');assert.equal($('h1').text().trim(),'Editorial guide');assert.equal($('meta[name=description]').attr('content'),'Authored search description.');assert.equal($('meta[property="og:title"]').attr('content'),'Authored social title');assert.equal($('meta[name="twitter:title"]').attr('content'),'Editorial card title','independent custom card title survives SEO edits');
 const editedGraph=JSON.parse($('script[type="application/ld+json"]').first().text()),webpage=editedGraph['@graph'].find(n=>n['@type']==='WebPage');assert.equal(webpage.name,'Authored search title');const originalGraph=parsed.meta.structured_data.flatMap(d=>d['@graph']||[d]),originalPage=originalGraph.find(n=>n['@type']==='WebPage');assert.ok(originalPage,'source WebPage schema is present');if(originalPage.description!==undefined)assert.equal(webpage.description,'Authored search description.');else assert.equal(webpage.description,undefined,'do not invent a schema description absent from the source');
 const postRecord=routes.find(r=>r.route==='/field-note-02/'),postFile=path.join(dir,'content',postRecord.collection,postRecord.slug+'.md'),post=parseContent(await readFile(postFile,'utf8'),postFile);if(kind==='yoast')assert.ok(JSON.stringify(post.meta.structured_data).includes('CommentAction'),'fixture exercises a real source comment action');post.meta.title='Authored article heading';post.meta.seo_title='Authored article search title';await writeFile(postFile,'---\n'+YAML.stringify(post.meta)+'---\n'+post.body);
 await run(process.execPath,['scripts/build.mjs','--site-url','https://export.example','--base-path','/preview'],{cwd:dir,timeout:120000});const postDOM=load(await output('field-note-02')),postGraph=JSON.parse(postDOM('script[type="application/ld+json"]').first().text())['@graph'],article=postGraph.find(n=>['Article','BlogPosting'].includes(n['@type']));assert.ok(article);assert.equal(postDOM('h1').text().trim(),'Authored article heading');assert.equal(article.headline,kind==='rankmath'?'Authored article search title':'Authored article heading');if(['rankmath','aioseo'].includes(kind))assert.equal(article.name,'Authored article search title');assert.ok(!JSON.stringify(postGraph).includes(origin),'post schema must not retain source service destinations');if(kind==='yoast'){assert.ok(!JSON.stringify(article).includes('CommentAction'));const seoReport=JSON.parse(await readFile(path.join(dir,'seo-preservation-report.json'),'utf8'));assert.ok(JSON.stringify(seoReport).includes('source-service-action-removed'));}
 // Route and indexability edits must update every generated SEO surface.
 parsed.meta.permalink='/renamed-guide/';await writeFile(file,'---\n'+YAML.stringify(parsed.meta)+'---\n'+parsed.body);
 const unlistedRecord=routes.find(r=>r.route==='/unlisted-guide/'),unlistedFile=path.join(dir,'content',unlistedRecord.collection,unlistedRecord.slug+'.md'),unlisted=parseContent(await readFile(unlistedFile,'utf8'),unlistedFile);unlisted.meta.robots='index,follow';await writeFile(unlistedFile,'---\n'+YAML.stringify(unlisted.meta)+'---\n'+unlisted.body);
 await run(process.execPath,['scripts/build.mjs','--site-url','https://export.example','--base-path','/preview'],{cwd:dir,timeout:120000});const renamed=load(await output('renamed-guide')),renamedGraph=renamed('script[type="application/ld+json"]').text();assert.equal(renamed('link[rel=canonical]').attr('href'),'https://export.example/preview/renamed-guide/');assert.equal(renamed('meta[property="og:url"]').attr('content'),'https://export.example/preview/renamed-guide/');assert.ok(!renamedGraph.includes('/editorial-guide/'));assert.ok(renamedGraph.includes('/renamed-guide/'));const rebuiltMap=await readFile(path.join(dir,'output/sitemap.xml'),'utf8');assert.ok(rebuiltMap.includes('/renamed-guide/'));assert.ok(!rebuiltMap.includes('/editorial-guide/'));assert.ok(rebuiltMap.includes('/unlisted-guide/'));assert.doesNotMatch(load(await output('unlisted-guide'))('meta[name=robots]').attr('content'),/noindex/);
 console.log(JSON.stringify({plugin:preset.plugin,version:preset.version,sourcePages:4,distinctSEOTitle:true,socialPreserved:true,graphRelocated:true,noindexPreserved:true,noindexExcludedFromSitemap:true,frontmatterRebuild:true,permalinkAndRobotsRebuild:true,articleTitleBinding:true,sourceServiceActionsRemoved:true,linkedPageSchemaUpdated:true,sourceWebPageDescription:originalPage.description!==undefined,aiCalls:0,scope:'Installed public metadata through native export and edited frontmatter; not full visual/plugin acceptance'}));
}finally{await rm(dir,{recursive:true,force:true});}
